    byte[] bytes,
    int aY,
    int aX,
    boolean ab,
    int bY,
    int bX,
    boolean bc,
    int cY,
    int cX,
    boolean ca) {
  assert bytes.length == 7 * BYTES;
  // rotate edges and place minX at the beginning
  if (bX < aX || cX < aX) {
    final int tempX = aX;
    final int tempY = aY;
    final boolean tempBool = ab;
    if (bX < cX) {
      aX = bX;
      aY = bY;
      ab = bc;
      bX = cX;
      bY = cY;
      bc = ca;
      cX = tempX;
      cY = tempY;
      ca = tempBool;
    } else {
      aX = cX;
      aY = cY;
      ab = ca;
      cX = bX;
      cY = bY;
      ca = bc;
      bX = tempX;
      bY = tempY;
      bc = tempBool;
    }
  } else if (aX == bX && aX == cX) {
    // degenerated case, all points with same longitude
    // we need to prevent that aX is in the middle (not part of the MBS)
    if (bY < aY || cY < aY) {
      final int tempX = aX;
      final int tempY = aY;
      final boolean tempBool = ab;
      if (bY < cY) {
        aX = bX;
        aY = bY;
        ab = bc;
        bX = cX;
        bY = cY;
        bc = ca;
        cX = tempX;
        cY = tempY;
        ca = tempBool;
      } else {
        aX = cX;
        aY = cY;
        ab = ca;
        cX = bX;
        cY = bY;
        ca = bc;
        bX = tempX;
        bY = tempY;
        bc = tempBool;
      }
    }
  }

  // change orientation if CW
  if (GeoUtils.orient(aX, aY, bX, bY, cX, cY) == -1) {
    // swap b with c
    final int tempX = bX;
    final int tempY = bY;
    final boolean tempBool = ab;
    // aX and aY do not change, ab becomes bc
    ab = bc;
    bX = cX;
    bY = cY;
    // bc does not change, ca becomes ab
    cX = tempX;
    cY = tempY;
    ca = tempBool;
  }

  final int minX = aX;
  final int minY = StrictMath.min(aY, StrictMath.min(bY, cY));
  final int maxX = StrictMath.max(aX, StrictMath.max(bX, cX));
  final int maxY = StrictMath.max(aY, StrictMath.max(bY, cY));

  int bits, x, y;
  if (minY == aY) {
    if (maxY == bY && maxX == bX) {
      y = cY;
      x = cX;
      bits = MINY_MINX_MAXY_MAXX_Y_X;
    } else if (maxY == cY && maxX == cX) {
      y = bY;
      x = bX;
      bits = MINY_MINX_Y_X_MAXY_MAXX;
    } else {
      y = bY;
      x = cX;
      bits = MINY_MINX_Y_MAXX_MAXY_X;
    }
